            "القيم هي المبادئ والمعاني التي تمنح حياتك اتجاهًا. قد تكون من أهم قيمك الأسرة، أو الحرية، أو التعلم، أو الاستقرار، أو الإبداع، أو مساعدة الآخرين، أو الاستقلال. هذه القيم لا تكون مجرد كلمات جميلة تكتبها في دفتر، بل تظهر في اختياراتك اليومية وفي الأشياء التي تقبل التضحية من أجلها والأشياء التي لا تستطيع التنازل عنها بسهولة.",
