            "حاول أن تفرق بين ما حدث في الماضي وما يحدث الآن. ربما كان موقف قديم سببًا في خوفك من التحدث أمام مجموعة، لكن الأشخاص الموجودين أمامك اليوم ليسوا بالضرورة الأشخاص أنفسهم، والظروف الحالية قد تكون مختلفة تمامًا. تذكير نفسك بهذا الفرق يساعدك على عدم التعامل مع كل موقف جديد باعتباره تكرارًا للموقف القديم.",
