        "افهم الفكرة جيدًا حتى تستطيع التعبير عنها بأكثر من صياغة. وإذا احتجت إلى ملاحظات أثناء العرض، استخدم كلمات مفتاحية قصيرة بدلًا من قراءة نص طويل."
