        "اسأل نفسك عن السبب الحقيقي: هل تخشى الفشل؟ أم حكم الآخرين؟ أم أنك لا تعرف من أين تبدأ؟ تحديد الخوف يجعله أكثر وضوحًا ويساعدك على اختيار خطوة مناسبة."
