  title: "بناء السمعة الشخصية: كيف تجعل أفعالك تتحدث عنك؟",
  category: "تطوير الذات",
  description: "تعرف إلى أسس السمعة الجيدة من خلال المصداقية والالتزام وجودة العمل واحترام الآخرين.",
